def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))

    def num(first, last, length):
        if length == 1:
            return first if first == last else None
        mid = [rng.randint(0, 9) for _ in range(length - 2)]
        return int(''.join(map(str, [first] + mid + [last])))

    def rand_num(digs, maxlen):
        while True:
            length = rng.randint(1, maxlen)
            f = rng.choice([d for d in digs if d != 0])
            l = rng.choice(digs)
            if length == 1:
                l = f
            v = num(f, l, length)
            if v is not None and 1 <= v <= 10 ** 9:
                return v

    tests = [
        fmt([14, 123, 323, 321, 431, 53635]),
        fmt([12, 13, 14, 15]),
        fmt([14, 13, 22, 19]),
        fmt([7]),
        fmt([10]),
        fmt([10 ** 9]),
        fmt([11, 11, 11, 11]),
        fmt([21, 12, 21, 12]),
        fmt([12, 21]),
        fmt([21, 12]),
        fmt([5, 55, 555, 5555]),
    ]
    for n in (2, 3, 4, 5, 6, 8, 10, 12):
        for _ in range(4):
            digs = rng.choice([[1, 2], [1, 2, 3], [1, 2, 3, 4, 5], list(range(10))])
            tests.append(fmt([rand_num(digs, rng.choice([2, 3, 4, 10])) for _ in range(n)]))
    for _ in range(3):
        tests.append(fmt([rng.randint(1, 10 ** 9) for _ in range(1000)]))
    # max-size
    tests.append(fmt([rng.randint(1, 10 ** 9) for _ in range(100000)]))
    tests.append(fmt([rand_num([1, 2, 3], 10) for _ in range(100000)]))
    tests.append(fmt([rand_num(list(range(10)), 3) for _ in range(100000)]))
    tests.append(fmt([rng.choice([12, 23, 31, 121, 232, 313]) for _ in range(100000)]))
    return tests

